import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { FaUser, FaEnvelope, FaCalendar, FaTrophy, FaFire, FaClock, FaSignOutAlt, FaCamera, FaHeart, FaTrash, FaImage } from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [user, setUser] = useState({
    name: '',
    email: '',
    joined: '',
    avatar: null
  });
  const [showAvatarOptions, setShowAvatarOptions] = useState(false);

  // Pre-built avatar images (emoji alternatives)
  const defaultAvatars = [
    { id: 1, emoji: '😊', name: 'Happy', color: '#f39c12' },
    { id: 2, emoji: '🧘', name: 'Zen', color: '#2ecc71' },
    { id: 3, emoji: '🦸', name: 'Hero', color: '#e74c3c' },
    { id: 4, emoji: '🧠', name: 'Smart', color: '#3498db' },
    { id: 5, emoji: '🌟', name: 'Star', color: '#f1c40f' },
    { id: 6, emoji: '💪', name: 'Strong', color: '#e67e22' },
    { id: 7, emoji: '🌸', name: 'Peaceful', color: '#e84393' },
    { id: 8, emoji: '🦋', name: 'Free', color: '#9b59b6' },
  ];

  useEffect(() => {
    const savedAvatar = localStorage.getItem('userAvatar');
    setUser({
      name: localStorage.getItem('userName') || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString(),
      avatar: savedAvatar
    });
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
    { icon: <FaHeart color="#e84393" />, value: '156', label: 'Moods Logged' },
  ];

  // Handle image upload
  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        setUser({ ...user, avatar: imageData });
        localStorage.setItem('userAvatar', imageData);
        setShowAvatarOptions(false);
      };
      reader.readAsDataURL(file);
    }
  };

  // Handle emoji/icon selection
  const handleEmojiSelect = (emoji) => {
    setUser({ ...user, avatar: emoji.emoji });
    localStorage.setItem('userAvatar', emoji.emoji);
    setShowAvatarOptions(false);
  };

  // Remove avatar
  const removeAvatar = () => {
    setUser({ ...user, avatar: null });
    localStorage.removeItem('userAvatar');
    setShowAvatarOptions(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    navigate('/');
  };

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your account and view your progress</p>
        </div>

        {/* Avatar Card */}
        <div style={styles.avatarCard}>
          <div style={styles.avatarContainer}>
            {/* Avatar Display */}
            <div style={styles.avatarWrapper}>
              {user.avatar && (user.avatar.startsWith('data:image') || user.avatar.includes('http')) ? (
                <img src={user.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : user.avatar ? (
                <div style={styles.avatarEmojiLarge}>{user.avatar}</div>
              ) : (
                <div style={styles.avatarPlaceholder}>
                  <FaUser size={50} color="#ccc" />
                </div>
              )}
              
              {/* Edit Button */}
              <button 
                style={styles.editAvatarBtn}
                onClick={() => setShowAvatarOptions(!showAvatarOptions)}
              >
                <FaCamera size={16} />
              </button>
            </div>

            <h2 style={styles.userName}>{user.name}</h2>
            <div style={styles.userInfo}>
              <div style={styles.infoRow}><FaEnvelope /> {user.email}</div>
              <div style={styles.infoRow}><FaCalendar /> Joined {user.joined}</div>
            </div>
          </div>

          {/* Avatar Picker Popup */}
          {showAvatarOptions && (
            <div style={styles.avatarPicker}>
              <div style={styles.pickerHeader}>
                <h4>Choose Your Avatar</h4>
                <button onClick={() => setShowAvatarOptions(false)} style={styles.closeBtn}>✕</button>
              </div>
              
              {/* Upload Image Option */}
              <div style={styles.uploadSection}>
                <label style={styles.uploadBtn}>
                  <FaImage /> Upload Image
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    style={{ display: 'none' }}
                  />
                </label>
              </div>

              {/* Default Emojis/Avatars */}
              <div style={styles.avatarGrid}>
                {defaultAvatars.map((avatar) => (
                  <div
                    key={avatar.id}
                    style={styles.avatarOption}
                    onClick={() => handleEmojiSelect(avatar)}
                  >
                    <span style={styles.avatarOptionEmoji}>{avatar.emoji}</span>
                    <span style={styles.avatarOptionName}>{avatar.name}</span>
                  </div>
                ))}
              </div>

              {/* Remove Avatar Option */}
              {user.avatar && (
                <button onClick={removeAvatar} style={styles.removeBtn}>
                  <FaTrash /> Remove Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Menu Card */}
        <div style={styles.menuCard}>
          <h3 style={styles.menuTitle}>Settings</h3>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>

        {/* Tips Card */}
        <div style={styles.tipsCard}>
          <h3 style={styles.tipsTitle}>💡 Pro Tip</h3>
          <p style={styles.tipsText}>Upload a photo or choose an emoji to personalize your profile! Your avatar helps make MindEase feel more like your space.</p>
        </div>
      </div>
    </div>
  );
}

